   214  void Decoder::Decode(const uint8_t *aData, uint16_t aLength)
   215  {
   216      while (aLength--)
   217      {
   218          uint8_t byte = *aData++;
   219
   220          switch (mState)
   221          {
   222          case kStateNoSync:
   223              if (byte == kFlagSequence)
   224              {
   225                  mState         = kStateSync;
   226                  mDecodedLength = 0;
   227                  mFcs           = kInitFcs;
   228              }
   229
   230              break;
   231
   232          case kStateSync:
   233              switch (byte)
   234              {
   235              case kEscapeSequence:
   236                  mState = kStateEscaped;
   237                  break;
   238
   239              case kFlagSequence:
   240
   241                  if (mDecodedLength > 0)
   242                  {
   243                      otError error = OT_ERROR_PARSE;
   244
   245                      if ((mDecodedLength >= kFcsSize)
   246  #ifndef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
   247                          && (mFcs == kGoodFcs)
   248  #endif
   249                      )
   250                      {
   251                          // Remove the FCS from the frame.
   252                          mWritePointer.UndoLastWrites(kFcsSize);
   253                          error = OT_ERROR_NONE;
   254                      }
   255
   256                      mFrameHandler(mContext, error);
   257                  }
   258
   259                  mDecodedLength = 0;
   260                  mFcs           = kInitFcs;
   261                  break;
   262
   263              default:
   264                  if (mWritePointer.CanWrite(sizeof(uint8_t)))
   265                  {
   266                      mFcs = UpdateFcs(mFcs, byte);
   267                      mWritePointer.WriteByte(byte);
   268                      mDecodedLength++;
   269                  }
   270                  else
   271                  {
   272                      mFrameHandler(mContext, OT_ERROR_NO_BUFS);
   273                      mState = kStateNoSync;
   274                  }
   275
   276                  break;
   277              }
   278
   279              break;
   280
   281          case kStateEscaped:
   282              if (mWritePointer.CanWrite(sizeof(uint8_t)))
   283              {
   284                  byte ^= 0x20;
   285                  mFcs = UpdateFcs(mFcs, byte);
   286                  mWritePointer.WriteByte(byte);
   287                  mDecodedLength++;
   288                  mState = kStateSync;
   289              }
   290              else
   291              {
   292                  mFrameHandler(mContext, OT_ERROR_NO_BUFS);
   293                  mState = kStateNoSync;
   294              }
   295
   296              break;
   297          }
   298      }
   299  }
